content.content:
 * its fiscal year start month (1 to 12, 1 unless set; a fiscal year FY<yyyy> starts on its first day in yyyy; not dated),
 * and the roles given to user names (clerk, the default, steward, or viewer — who sees everything and can change nothing),
 * and the delegations of the steward role (a steward delegates it to a user from a from-date to a to-date, inclusive,
 * by the sheet's today; a blank from-date is the sheet's today, a blank to-date the from-date). A save sets only the settings
 * whose fields were touched since the last one. The clerk limit, the floor, the terms (the sheet's and
 * each grade's), the grace days of each grade, the late percent, the cap, the proof threshold (the sheet's and each grade's), the note threshold, the review threshold and the rounding mode are dated: a save records each from its from-date (blank
 * is the sheet's today), and each shows the value in force on the sheet's today.
 */
/** The edit with each field the save sent (as it sent it) untouched again. */
function untouchSent(was: SettingsEdit, sent: SettingsEdit): SettingsEdit {
  const scalar = (v: string | null, s: string | null) => (v === null || v.trim() === s ? null : v);
  const map = (v: Record<string, string>, s: Record<string, string>) =>
    Object.fromEntries(Object.entries(v).filter(([k, x]) => x.trim() !== s[k]));
  const next = { ...was };
  for (const key of Object.keys(was) as (keyof SettingsEdit)[]) {
    if (key === 'gradeTerms' || key === 'gradeGrace' || key === 'gradeProof' || key === 'perms') {
      next[key] = map(was[key], sent[key]);
    } else {
      next[key] = scalar(was[key], sent[key]);
    }
  }
  return next;
}

function SettingsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data } = useSettings(sheet);
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;
  const [edit, setEdit] = useState<SettingsEdit>({ clerkLimit: null, floor: null, terms: null, latePct: null, policyDate: null, periodNumberingFrom: null, cap: null, proofThreshold: null, noteThreshold: null, graceDays: null, entryDate: null, pot: null, parent: null, fiscalStartMonth: null, alertThreshold: null, rounding: null, reviewThreshold: null, escalateAfter: null, reviewSla: null, gradeTerms: {}, gradeGrace: {}, gradeProof: {}, perms: {} });
  const [froms, setFroms] = useState<Froms>({});
  const [limitInvalid, setLimitInvalid] = useState(false);
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [roleInvalid, setRoleInvalid] = useState(false);
  const [delegate, setDelegate] = useState({ name: '', from: '', to: '' });
  const [delegateInvalid, setDelegateInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const saveSettings = useMutation({
    mutationFn: ({ e, from }: { e: SettingsEdit; from: Froms }) => postJson<Settings>(`${base}/settings`, { ...e, from, user }),
    onSuccess: (saved, sent) => {
      // A field changed again while the save was in flight stays touched for the next save.
      setEdit((was) => untouchSent(was, sent.e));
      setFroms((was) => Object.fromEntries(Object.entries(was).filter(([k, v]) => v.trim() !== '' && v.trim() !== sent.from[k])));
      queryClient.setQueryData(settingsKey(sheet), saved);
      // The pot decides each pool member's cut.
      void queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
      // A grade with no rate of its own takes the parent sheet's.
      void queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
      // The policy date and the rounding mode decide how each claim's live figures round.
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const saveRole = useMutation({
    mutationFn: (r: { name: string; role: string }) => postJson<Settings>(`${base}/roles`, { ...r, user }),
    onSuccess: (saved) => {
      setName('');
      setRole('');
      queryClient.setQueryData(settingsKey(sheet), saved);
    },
  });

  const saveDelegation = useMutation({
    mutationFn: (d: { name: string; from: string; to: string }) => postJson<Settings>(`${base}/delegations`, { ...d, user }),
    onSuccess: (saved) => {
      setDelegate({ name: '', from: '', to: '' });
      queryClient.setQueryData(settingsKey(sheet), saved);
    },
  });

  // An error goes as soon as its form is changed or submitted again.
